function minimumCoins(prices) {
  const n = prices.length;
  const dp = new Array(n).fill(0);
  const deque = [];
  let front = 0;
  for (let i = n - 1; i >= 0; i--) {
    while (front < deque.length && deque[front] > 2 * i + 2) {
      front++;
    }
    if (2 * i + 2 >= n) {
      dp[i] = prices[i];
    } else {
      dp[i] = prices[i] + dp[deque[front]];
    }
    while (deque.length > front && dp[deque[deque.length - 1]] >= dp[i]) {
      deque.pop();
    }
    deque.push(i);
  }
  return dp[0];
}

