function minimumCoins(prices) {
  // Try every set of fruits to buy; fruit index k (0-based) covers indices k + 1 .. 2k + 1.
  const n = prices.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let cost = 0;
    const owned = new Array(n).fill(false);
    for (let k = 0; k < n; k++) {
      if (!(mask & (1 << k))) continue;
      cost += prices[k];
      owned[k] = true;
      for (let j = k + 1; j <= 2 * k + 1 && j < n; j++) owned[j] = true;
    }
    if (owned.every(Boolean)) best = Math.min(best, cost);
  }
  return best;
}

