function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const shape = Math.floor(rand() * 3);
    const prices = Array.from({ length: n }, (_, i) => {
      if (shape === 0) return 1 + Math.floor(rand() * 100000);
      if (shape === 1) return rand() < 0.1 ? 1 + Math.floor(rand() * 10) : 50000 + Math.floor(rand() * 50001);
      return Math.max(1, 100000 - i * 50 - Math.floor(rand() * 40));
    });
    return [prices];
  }
  const n = 1 + Math.floor(rand() * 10);
  const span = rand() < 0.5 ? 5 : 100;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * span))];
}
